"""Player decision projection, not matchup accuracy or human comprehension tests."""
import subprocess,unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PRELUDE="""const assert=require('node:assert/strict'),E=require('./web_r4/loading-engine.js'),C=require('./web_r4/loading-coach.js'),c=require('./web_r4/loading-data.json');
function run(i=0,s={},p={},risk='BALANCED',period='LEVEL1'){let x=E.exampleInput(c,i);x.schema_version='lol-coach-loading-input-v4';x.preferences={risk};x.scenario={standard:'lane-standard-v1',overrides:s};x.planning={basis:'loading-plan-example-v1',overrides:p};const r=E.analyze(x,c);r.coach=C.evaluate(r,c,r.input.scenario,period);return r;}
"""
class PlayerPlanboardTests(unittest.TestCase):
 def test_team_plan_and_roles_use_actual_functions_not_example_roster(self):
  self.node("const r=run(),b=r.coach.planboard;assert.equal(b.team_plan.rows.length,6);assert.equal(b.team_plan.phases.length,3);assert.equal(b.team_plan.observation,false);assert.equal(b.team_plan.ours.prepared,true);assert.equal(b.team_plan.theirs.prepared,false);assert.match(b.team_plan.theirs.field,/옆으로/);assert.match(b.team_plan.theirs.damage,/같은 대상.*집중/);assert.match(b.team_plan.theirs.macro,/피오라.*사이드/);assert.match(b.team_plan.ours.damage,/모두.*진입/);assert(b.condition_responses.fight.some(x=>x.id==='FRONT_DEEP'));for(const area of ['lane','operations','fight'])assert.equal(b.action_summaries[area].items.length,5);assert.equal(b.reminders.length,3);function analyze(x){return E.analyze(x,c).coach.planboard;}for(const [own,pos] of [['Ahri','MID'],['Sejuani','JUNGLE']]){const x=E.exampleInput(c,0);x.own_champion=own;x.own_position=pos;const a=analyze(x);assert(a.role_principles);assert.notEqual(a.fight.setup,b.fight.setup);assert.equal(a.action_summaries.lane.items.length,5);assert(a.condition_responses.fight.some(x=>x.id==='ROLE_PLAN_BREAKS'));assert(!a.fight.awareness);assert.equal(a.coverage.status,'UNSUPPORTED');assert(a.role_principles.evidence_ids.every(x=>x.includes(own)));}const x=E.exampleInput(c,0);x.allies.find(x=>x.champion==='Lux').champion='Brand';let a=analyze(x);assert.equal(a.team_plan.ours.prepared,false);assert(!a.team_plan.ours.damage.includes('럭스'));assert.match(a.team_plan.ours.damage,/보호.*자료/);x.enemies.find(x=>x.champion==='Fiora').champion='Malphite';a=analyze(x);assert(!a.team_plan.theirs.macro.includes('피오라'));assert(!a.condition_responses.operations.some(x=>x.id==='SIDE_PRESSURE'));assert(!a.condition_responses.lane.some(x=>x.id==='LUX_BIND_HIT'));assert.equal(a.wave.plan_id,'CHECK_WAVE');")
 def test_situations_preserve_failures_and_provenance_without_live_claims(self):
  self.node("const b=run().coach.planboard;for(const id of ['LUX_BIND_HIT','LUX_BIND_MISSED']){const a=b.condition_responses.lane.find(x=>x.id===id);assert(a.reason);assert(a.stop);assert.equal(a.observation,false);assert(a.evidence_ids.length);assert(a.rule_ids.length);}assert.match(b.condition_responses.lane.find(x=>x.id==='LUX_BIND_HIT').stop,/배우지/);assert.match(b.condition_responses.fight.find(x=>x.id==='FRONT_DEEP').action,/따라가지|도울 수/);for(const risk of ['LOSS_LIMIT','OPPORTUNITY']){const r=run(0,{}, {},risk).coach.planboard;assert.deepEqual(r.team_plan,b.team_plan);}const low=run(0,{resources:'LOW'}).coach.planboard;assert.notEqual(low.wave.combat,b.wave.combat);assert.equal(low.condition_responses.lane[0].action,run(0,{resources:'LOW',enemy_key:'SPENT'}).coach.planboard.wave.combat);")
 def test_carry_priorities_connect_specific_threats_to_macro_and_fight(self):
  self.node("const b=run().coach.planboard,a=b.operations.awareness;assert(a);assert.deepEqual(a.actors,['LeeSin','Zed']);assert.equal(a.observation,false);assert.equal(a.actual_positions,null);assert.match(a.watch,/리 신.*제드.*포탑|제드.*리 신.*포탑/);assert.match(a.missing,/미니언/);assert.match(a.missing,/혼자|아군/);assert.equal(b.condition_responses.operations[0].action,a.missing);assert.equal(b.condition_responses.fight[0].action,b.fight.awareness.entered);assert.match(b.fight.start,/앞.*적|닿는 적/);assert(!b.fight.start.startsWith('아군 제어가 적중'));assert.match(b.fight.awareness.reserve,/90구경 투망\\(E\\)/);assert.match(b.fight.target,/카이사/);assert.match(b.fight.combo,/요들잡이 덫\\(W\\)/);assert.equal(b.action_summaries.fight.items[3].text,b.fight.awareness.danger);assert.equal(b.loading_summary.items[3].conclusion,b.fight.start.split('. ')[0]+'.');assert.equal(b.condition_responses.lane[0].action,run(0,{enemy_key:'SPENT'}).coach.planboard.wave.combat);assert.match(b.condition_responses.lane[0].action,/럭스.*공간|럭스.*막타/);assert.match(b.condition_responses.lane[0].action,/미니언/);assert.match(run(0,{}, {},'BALANCED','LEVEL6').coach.planboard.condition_responses.lane[0].action,/폭뢰\\(R\\)/);")
 def test_priority_rules_do_not_copy_absent_actors_or_change_strength(self):
  self.node("let x=run().input;const base=E.analyze(x,c);x.enemies.find(p=>p.champion==='Zed').champion='Viktor';let b=E.analyze(x,c).coach.planboard;assert.deepEqual(b.operations.awareness.actors,['LeeSin']);assert(!JSON.stringify([b.operations.awareness,b.fight.awareness]).includes('제드'));x.enemies.find(p=>p.champion==='LeeSin').champion='Ivern';b=E.analyze(x,c).coach.planboard;assert(!b.operations.awareness);assert(!b.condition_responses.operations.some(x=>x.id==='FLANK_UNSEEN'));x=run().input;x.allies.find(p=>p.champion==='Lux').champion='Janna';b=E.analyze(x,c).coach.planboard;assert(!JSON.stringify([b.operations.awareness,b.fight.awareness]).includes('럭스'));assert.match(b.fight.setup,/오른.*세주아니/);x=run().input;x.own_champion='Ornn';x.own_position='TOP';assert(!E.analyze(x,c).coach.planboard.operations.awareness);x=run().input;x.patch='1.1';assert(!E.analyze(x,c).coach.planboard.operations.awareness);for(const risk of ['LOSS_LIMIT','OPPORTUNITY']){const r=run(0,{}, {},risk);assert.deepEqual(r.coach.periods,base.coach.periods);assert.deepEqual(r.coach.planboard.operations.awareness,base.coach.planboard.operations.awareness);assert.equal(r.coach.planboard.fight.kill,'UNDETERMINED');}assert(!run(0,{}, {enemy_jungle:'AWAY'}).coach.planboard.operations.awareness.actual_positions);")
 def test_condition_cards_use_same_rule_and_keep_other_gates(self):
  self.node("const a=run().coach.planboard,cards=a.condition_responses;assert(cards);const q=cards.lane[0];assert.equal(q.id,'ENEMY_KEY_SPENT');assert.match(q.trigger,/노틸러스의 닻줄 견인\\(Q\\)/);assert.equal(q.action,run(0,{enemy_key:'SPENT'}).coach.planboard.wave.combat);assert.match(q.keep,/강력한 일격\\(P\\).*카이사/);assert.equal(q.scenario_patch.enemy_key,'SPENT');for(const [s,p]of [[{resources:'LOW'},{}],[{wave:'UNKNOWN'},{}],[{engage:'THEIRS'},{}],[{},{enemy_jungle:'NEAR'}],[{},{goal:'RECALL',clear_window:'OPEN'}]]){const r=run(0,s,p).coach.planboard;assert.equal(r.condition_responses.lane[0].action,run(0,{...s,enemy_key:'SPENT'},p).coach.planboard.wave.combat);}for(const area of ['lane','operations','fight'])for(const x of cards[area]){assert.equal(x.observation,false);assert.equal(x.basis,'DESIGN_HYPOTHESIS');assert(x.trigger&&x.action&&x.keep&&x.stop);assert(x.source_paths.length&&x.rule_ids.length);}assert.equal(cards.operations.find(x=>x.id==='LATE_JOIN').action,a.operations.late_join);assert.equal(cards.fight.find(x=>x.id==='FOLLOWUP_WINDOW').action,a.fight.combo);assert.equal(cards.fight.find(x=>x.id==='CONNECTION_LOST').action,a.fight.stop);assert(!cards.fight.some(x=>x.scenario_patch));")
 def test_condition_cards_scope_role_and_preference_without_strength_promotion(self):
  self.node("const a=run(),f=run(1).coach.planboard;assert.equal(f.condition_responses.fight[0].trigger,'아군과 같은 대상을 공격할 수 있다면');assert.notEqual(f.condition_responses.operations[0].id,a.coach.planboard.condition_responses.operations[0].id);const x=run().input;x.own_champion='Ahri';x.own_position='MID';const u=E.analyze(x,c).coach.planboard;assert(!u.condition_responses.lane.some(x=>x.scenario_patch));assert(!u.condition_responses.lane.some(x=>x.actors.includes('Nautilus')));assert.equal(u.condition_responses.lane[0].knowledge_state,'GENERAL_PRINCIPLE');for(const risk of ['LOSS_LIMIT','OPPORTUNITY']){const r=run(0,{}, {},risk);assert.deepEqual(r.coach.periods,a.coach.periods);assert.deepEqual(r.coach.planboard.condition_responses.fight,a.coach.planboard.condition_responses.fight);}x.own_champion='Caitlyn';x.own_position='BOTTOM';x.patch='1.1';assert(!E.analyze(x,c).coach.planboard.condition_responses.lane.some(x=>x.scenario_patch));")
 def node(self,body):
  r=subprocess.run(['node','-e',PRELUDE+body],cwd=ROOT,capture_output=True,text=True)
  self.assertEqual(r.returncode,0,r.stderr[-4000:])
 def test_four_sentence_briefing_uses_same_report_without_changing_strength(self):
  self.node("const a=run(),b=a.coach.planboard.briefing_v2;assert(b,'missing four-sentence briefing');assert.deepEqual(b.items.map(x=>x.id),['our_plan','enemy_plan','my_role','key_change']);assert(b.items.every(x=>x.text&&x.target));assert(b.items.every(x=>x.text.split(/[.!?]\\s+/).filter(Boolean).length===1));assert.equal(b.origin,'ANALYSIS_ASSUMPTIONS_NOT_OBSERVATION');for(const risk of ['LOSS_LIMIT','OPPORTUNITY'])assert.deepEqual(a.coach.periods,run(0,{}, {},risk).coach.periods);const f=run(1).coach.planboard.briefing_v2;assert.notEqual(f.items[0].text,b.items[0].text);const u=run(1).input;u.patch='1.1';assert.equal(E.analyze(u,c).coach.planboard.coverage.status,'UNSUPPORTED');assert(E.analyze(u,c).coach.planboard.briefing_v2.limits.includes('조건')); ")
 def test_plain_wording_explains_actions_without_changing_stored_text(self):
  self.node("const P=require('./web_r4/loading-planboard.js'),before=JSON.stringify(require('./web_r4/loading-knowledge.json'));assert.equal(typeof P.plainLanguage,'function');const text=P.plainLanguage('수급 공간에서 처리 자원을 남긴다. 빠른 처리와 크래시를 구분한다. 후속 거리가 끊기면 본대와 연결한다.');assert(!/수급|처리|후속 거리|본대와 연결/.test(text));assert.match(text,/미니언/);assert.match(text,/마나|기술/);assert.equal(P.plainLanguage(text),text);assert.equal(P.plainLanguage('처리량을 조절한다.'),'미니언을 잡는 속도를 조절한다.');assert.equal(before,JSON.stringify(require('./web_r4/loading-knowledge.json')));assert.equal(P.plainLanguage('riot.txt · 16.20 · 1승 / 1경기'),'riot.txt · 16.20 · 1승 / 1경기');")
 def test_each_area_explains_actual_lane_or_team_composition_not_winner_from_tags(self):
  self.node("const a=run().coach.planboard,f=run(1).coach.planboard;for(const area of ['lane','operations','fight'])for(const key of ['ours','theirs','matchup','action'])assert(a.area_context[area][key]);assert.match(a.area_context.lane.ours,/케이틀린.*럭스/);assert.match(a.area_context.lane.theirs,/카이사.*노틸러스/);assert(!/오른|세주아니|아리/.test(a.area_context.lane.ours));assert.match(f.area_context.lane.matchup,/급소|견제/);assert.notEqual(a.area_context.operations.matchup,f.area_context.operations.matchup);assert.equal(a.area_context.fight.winner,'UNDETERMINED');for(const risk of ['LOSS_LIMIT','OPPORTUNITY']){const b=run(0,{}, {},risk).coach.planboard;for(const area of ['lane','operations','fight'])assert.equal(a.area_context[area].matchup,b.area_context[area].matchup);}const x=run().input;x.allies.reverse();x.enemies.reverse();assert.deepEqual(E.analyze(x,c).coach.planboard.area_context,a.area_context);const changed=run().input;changed.allies.find(p=>p.position==='SUPPORT').champion='Janna';const b=E.analyze(changed,c).coach.planboard;assert.match(b.area_context.lane.ours,/잔나/);assert(!b.area_context.lane.ours.includes('럭스'));assert(!b.area_context.lane.matchup.includes('케이틀린·럭스')); ")
 def test_context_respects_patch_actual_team_capabilities_and_selected_period(self):
  self.node("const x=run(1).input;x.patch='1.1';const a=E.analyze(x,c).coach.planboard;assert(!a.loading_summary.items[1].conclusion.includes('방어 아이템'));const y=run(1).input;for(const [i,ch]of ['Graves','Zed','Kaisa','Yunara'].entries())y.allies.filter(p=>p.champion!=='Fiora')[i].champion=ch;const b=E.analyze(y,c).coach.planboard;assert(!b.area_context.operations.ours.includes('보호·방해'));assert(!run(3,{}, {},'BALANCED','LEVEL6').coach.planboard.area_context.lane.matchup.includes('Lv1 시작 기술')); ")
 def test_loading_direction_has_four_decisions_and_bounded_exceptions(self):
  self.node("for(const i of [0,1,2,3,4]){const a=run(i).coach.planboard,b=a.loading_summary;assert(b,'missing compact loading direction');assert.deepEqual(b.items.map(v=>v.id),['lane','growth','operations','fight']);assert(b.changes.length<=3);assert(b.items.every(v=>v.conclusion&&v.support));assert(!b.items[0].conclusion.includes('막타 중심으로 천천히'));}const a=run().coach.planboard;assert.match(a.loading_summary.items[0].conclusion,/멀리서.*막타.*먼저/);const low=run(0,{resources:'LOW'}).coach.planboard;assert.match(low.loading_summary.items[0].conclusion,/CS|경험치|수급/);assert.notEqual(low.loading_summary.items[0].conclusion,a.loading_summary.items[0].conclusion);assert.deepEqual(run(0,{}, {},'LOSS_LIMIT').coach.planboard.loading_summary.items[1],run(0,{}, {},'OPPORTUNITY').coach.planboard.loading_summary.items[1]);")
 def test_loading_conclusion_tracks_active_scope_not_initial_pressure(self):
  self.node("for(const state of [{wave:'UNKNOWN'},{wave:'UNDER_TOWER'},{wave:'INCOMING'},{engage:'THEIRS'},{engage:'OURS'}]){const a=run(0,state).coach.planboard.loading_summary.items[0];assert(!/사거리 견제로 막타 접근을 늦추고|먼저 처리 여유/.test(a.conclusion+' '+a.support));}const a=run(0,{}, {goal:'RECALL'}).coach.planboard.loading_summary.items[0];assert.match(a.conclusion,/귀환|구매/);assert(!/먼저 처리 여유/.test(a.support));for(const i of [0,1,2,3,4,5]){const b=run(i,{}, {goal:'PRESSURE'},'BALANCED','LEVEL2').coach.planboard.loading_summary;assert(!b.items.slice(2).some(x=>/바꾼다|끊기면/.test(x.support)),'do not append extra switches beyond shared three');assert(b.items.every(x=>(x.conclusion.match(/\\. /g)||[]).length===0));}")
 def test_fiora_statistics_expert_and_counterplay_bridge_does_not_invent_strength(self):
  self.node("const a=run(1).coach,b=a.planboard.evidence_bridge;assert(b,'missing statistical to guide bridge');assert.equal(b.statistics.matchup.outcome.n,1);assert.equal(b.statistics.matchup.matchup.points.length,0);assert.equal(b.statistics.tactical_confirmation,false);assert.equal(b.expert.source_ids.length,2);assert.match(b.expert.plan,/수급|마나/);assert.equal(b.counterplay.opponent_goal,a.planboard.matchup_playbook.theirs.purpose);assert.match(b.counterplay.opponent_goal,/말파이트의 지진의 파편\\(Q\\)/);assert.equal(b.counterplay.wave_plan,a.planboard.wave.label);assert.equal(b.counterplay.growth,a.planboard.loading_summary.items[1].conclusion);for(const p of a.periods)for(const m of Object.values(p.metrics))assert.equal(m.assessment,'INSUFFICIENT');const k={...c,coaching_knowledge:structuredClone(require('./web_r4/loading-knowledge.json'))};delete k.coaching_knowledge.statistical_context.matchups.E;const x=E.exampleInput(k,1),r=E.analyze(x,k).coach;assert.equal(r.planboard.evidence_bridge.statistics.matchup,null);assert.equal(r.supported,true);assert.equal(r.planboard.loading_summary.items.length,4); ")
 def test_default_has_three_time_scales_and_four_separate_axes(self):
  self.node("const r=E.analyze(E.exampleInput(c,0),c),b=r.coach.planboard;assert(b,'missing player planboard');assert(b.lane.overall_goal);assert(b.lane.milestone.goal);assert(b.wave.purpose);assert.equal(b.wave.plan_id,'ACQUIRE_PUSH');for(const k of ['pace','pressure','exposure','resources'])assert(b.wave.axes[k]);assert(b.wave.next_wave);assert.equal(b.wave.state.minion_size,'UNOBSERVED');assert.equal(b.wave.completed,false);assert.equal(b.reminders.length,3);assert(b.quick_scenarios.length<=2);")
 def test_versioned_hypotheses_are_not_observations(self):
  self.node("const r=run(0,{}, {enemy_jungle:'AWAY',enemy_support:'ABSENT'});assert.equal(r.input.schema_version,'lol-coach-loading-input-v4');assert.equal(r.coach.context.observations.resources,null);assert.equal(r.coach.planboard.context.origin,'HYPOTHETICAL_LOADING_EXAMPLE');assert.equal(r.coach.planboard.context.actual_enemy_positions,null);let x=E.exampleInput(c,0);x.schema_version='lol-coach-loading-input-v3';x.preferences={risk:'BALANCED'};x.scenario={standard:'lane-standard-v1',overrides:{}};const a=E.analyze(x,c);assert(a.coach.planboard);x.planning={basis:'loading-plan-example-v1',overrides:{}};assert.throws(()=>E.analyze(x,c));x.schema_version='lol-coach-loading-input-v4';x.planning.overrides.actual_enemy_x=10;assert.throws(()=>E.analyze(x,c));")
 def test_jungle_exposure_is_not_processing_speed_or_automatic_retreat(self):
  self.node("const a=run().coach.planboard,b=run(0,{}, {enemy_jungle:'NEAR'}).coach.planboard;assert.equal(a.wave.plan_id,b.wave.plan_id);assert.equal(a.wave.axes.pace.id,b.wave.axes.pace.id);assert.notEqual(a.wave.axes.exposure.id,b.wave.axes.exposure.id);assert.notEqual(a.wave.axes.pressure.id,b.wave.axes.pressure.id);assert(b.wave.handling.includes('막타'));assert(b.wave.next_wave.includes('상대 쪽'));assert.equal(a.context.planning.overrides.enemy_jungle,undefined);")
